-- Bounded state-budget pilot; independent from PGE credits and ESA S13 accounts.
CREATE TABLE public.budget_execution (
  scope text NOT NULL CHECK (scope='ES_STATE_BUDGET'),
  period text NOT NULL CHECK (period ~ '^20[0-9]{2}-(0[1-9]|1[0-2])$'),
  chapter text NOT NULL CHECK (chapter IN ('1','2','3','4','5','6','7','8','9','NF','FIN','TOTAL')),
  credit numeric(18,3) CHECK (credit >= 0 AND credit <> 'NaN'::numeric),
  committed numeric(18,3) CHECK (committed >= 0 AND committed <> 'NaN'::numeric),
  obligations numeric(18,3) CHECK (obligations >= 0 AND obligations <> 'NaN'::numeric),
  payments numeric(18,3) CHECK (payments >= 0 AND payments <> 'NaN'::numeric),
  unit text NOT NULL CHECK (unit='MILES_EUR'),
  raw_data jsonb NOT NULL,
  PRIMARY KEY(scope,period,chapter),
  CHECK (chapter NOT IN ('NF','FIN','TOTAL') OR
    (credit IS NOT NULL AND committed IS NOT NULL AND obligations IS NOT NULL AND payments IS NOT NULL))
);
ALTER TABLE public.budget_execution ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_execution_read ON public.budget_execution FOR SELECT TO anon,authenticated USING(true);
GRANT SELECT ON public.budget_execution TO anon,authenticated;
GRANT ALL ON public.budget_execution TO service_role;

